-- Nosso Mercadinho: PostgreSQL/Supabase baseline, including every runtime extension.
-- Structural only: use the SQLite importer for an existing installation.
-- Optional seed.sql is exclusively for a new installation, after these migrations.
-- Authentication and store authorization stay in Express; no auth.users dependency.
-- Dates, JSON/XML and 0/1 flags intentionally retain their SQLite representation.
BEGIN;
SET LOCAL search_path TO public, pg_catalog;

CREATE TABLE IF NOT EXISTS public."clientes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" text NOT NULL,
  "cpf" text NOT NULL,
  "telefone" text NOT NULL,
  "limite_credito" numeric NOT NULL DEFAULT 0,
  "ativo" integer NOT NULL DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "clientes_cpf_key" UNIQUE ("cpf")
);

CREATE TABLE IF NOT EXISTS public."empresas" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" text NOT NULL,
  "razao_social" text,
  "cnpj" text,
  "ativo" integer DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS public."financeiro_categorias" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "empresa_id" bigint,
  "nome" text NOT NULL,
  "tipo" text NOT NULL DEFAULT 'AMBOS',
  "ativo" integer NOT NULL DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "financeiro_categorias_check_1" CHECK (tipo IN ('ENTRADA', 'SAIDA', 'AMBOS')),
  CONSTRAINT "financeiro_categorias_empresa_id_fkey" FOREIGN KEY ("empresa_id") REFERENCES public."empresas" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."fornecedores" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "empresa_id" bigint,
  "tipo_pessoa" text DEFAULT 'JURIDICA',
  "nome_fantasia" text,
  "razao_social" text NOT NULL,
  "cpf_cnpj" text,
  "inscricao_estadual" text,
  "inscricao_municipal" text,
  "telefone" text,
  "whatsapp" text,
  "email" text,
  "site" text,
  "contato_nome" text,
  "contato_cargo" text,
  "contato_telefone" text,
  "contato_email" text,
  "cep" text,
  "endereco" text,
  "numero" text,
  "complemento" text,
  "bairro" text,
  "cidade" text,
  "estado" text,
  "prazo_pagamento_dias" integer DEFAULT 0,
  "observacao" text,
  "ativo" integer DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "fornecedores_cpf_cnpj_key" UNIQUE ("cpf_cnpj"),
  CONSTRAINT "fornecedores_empresa_id_fkey" FOREIGN KEY ("empresa_id") REFERENCES public."empresas" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."lojas" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "empresa_id" bigint,
  "nome" text NOT NULL,
  "codigo" text,
  "tipo" text DEFAULT 'FILIAL',
  "cnpj" text,
  "endereco" text,
  "numero" text,
  "complemento" text,
  "bairro" text,
  "cidade" text,
  "estado" text,
  "cep" text,
  "telefone" text,
  "ativo" integer DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "lojas_empresa_id_fkey" FOREIGN KEY ("empresa_id") REFERENCES public."empresas" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."clientes_lojas" (
  "cliente_id" bigint NOT NULL,
  "loja_id" bigint NOT NULL,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "clientes_lojas_pkey" PRIMARY KEY ("cliente_id", "loja_id"),
  CONSTRAINT "clientes_lojas_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "clientes_lojas_cliente_id_fkey" FOREIGN KEY ("cliente_id") REFERENCES public."clientes" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."fornecedores_lojas" (
  "fornecedor_id" bigint NOT NULL,
  "loja_id" bigint NOT NULL,
  "ativo" integer NOT NULL DEFAULT 1,
  "dados_json" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "fornecedores_lojas_pkey" PRIMARY KEY ("fornecedor_id", "loja_id"),
  CONSTRAINT "fornecedores_lojas_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "fornecedores_lojas_fornecedor_id_fkey" FOREIGN KEY ("fornecedor_id") REFERENCES public."fornecedores" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."locais_estoque" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "loja_id" bigint NOT NULL,
  "nome" text NOT NULL,
  "tipo" text NOT NULL,
  "permite_venda" integer DEFAULT 0,
  "ativo" integer DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "locais_estoque_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."migracoes_cadastros_lojas" (
  "chave" text NOT NULL,
  CONSTRAINT "migracoes_cadastros_lojas_pkey" PRIMARY KEY ("chave")
);

CREATE TABLE IF NOT EXISTS public."papeis_acesso" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" text NOT NULL,
  "permissoes" text NOT NULL DEFAULT '[]',
  "sistema" integer NOT NULL DEFAULT 0,
  "acesso_todas_lojas" integer NOT NULL DEFAULT 0,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "papeis_acesso_nome_key" UNIQUE ("nome")
);

CREATE TABLE IF NOT EXISTS public."produtos" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ean" text NOT NULL,
  "nome" text NOT NULL,
  "marca" text,
  "foto" text,
  "categoria" text,
  "fornecedor" text,
  "preco_custo" numeric DEFAULT 0,
  "preco_venda" numeric DEFAULT 0,
  "estoque" numeric DEFAULT 0,
  "estoque_minimo" numeric DEFAULT 0,
  "unidade_medida" text,
  "ncm" text,
  "cest" text,
  "descricao_ncm" text,
  "ativo" integer DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "produtos_ean_key" UNIQUE ("ean")
);

CREATE TABLE IF NOT EXISTS public."estoque_saldos" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "produto_id" bigint NOT NULL,
  "loja_id" bigint NOT NULL,
  "local_id" bigint NOT NULL,
  "quantidade" numeric DEFAULT 0,
  "custo_medio" numeric DEFAULT 0,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "estoque_saldos_produto_id_loja_id_local_id_key" UNIQUE ("produto_id", "loja_id", "local_id"),
  CONSTRAINT "estoque_saldos_local_id_fkey" FOREIGN KEY ("local_id") REFERENCES public."locais_estoque" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "estoque_saldos_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "estoque_saldos_produto_id_fkey" FOREIGN KEY ("produto_id") REFERENCES public."produtos" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."fornecedor_precos_historico" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fornecedor_id" bigint NOT NULL,
  "produto_id" bigint NOT NULL,
  "custo_unitario" numeric NOT NULL,
  "quantidade" numeric DEFAULT 0,
  "numero_nota" text,
  "chave_nfe" text,
  "data_compra" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "observacao" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "loja_id" bigint,
  CONSTRAINT "fornecedor_precos_historico_produto_id_fkey" FOREIGN KEY ("produto_id") REFERENCES public."produtos" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "fornecedor_precos_historico_fornecedor_id_fkey" FOREIGN KEY ("fornecedor_id") REFERENCES public."fornecedores" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "fornecedor_precos_historico_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."fornecedor_produtos" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fornecedor_id" bigint NOT NULL,
  "produto_id" bigint NOT NULL,
  "codigo_produto_fornecedor" text,
  "ultimo_custo" numeric DEFAULT 0,
  "menor_custo" numeric DEFAULT 0,
  "maior_custo" numeric DEFAULT 0,
  "custo_medio" numeric DEFAULT 0,
  "quantidade_comprada" numeric DEFAULT 0,
  "ultima_compra_em" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "fornecedor_produtos_fornecedor_id_produto_id_key" UNIQUE ("fornecedor_id", "produto_id"),
  CONSTRAINT "fornecedor_produtos_produto_id_fkey" FOREIGN KEY ("produto_id") REFERENCES public."produtos" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "fornecedor_produtos_fornecedor_id_fkey" FOREIGN KEY ("fornecedor_id") REFERENCES public."fornecedores" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."fornecedor_produtos_lojas" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fornecedor_id" bigint NOT NULL,
  "produto_id" bigint NOT NULL,
  "loja_id" bigint NOT NULL,
  "codigo_produto_fornecedor" text,
  "ultimo_custo" numeric DEFAULT 0,
  "menor_custo" numeric DEFAULT 0,
  "maior_custo" numeric DEFAULT 0,
  "custo_medio" numeric DEFAULT 0,
  "quantidade_comprada" numeric DEFAULT 0,
  "ultima_compra_em" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "fornecedor_produtos_lojas_fornecedor_id_produto_id_loja_id_key" UNIQUE ("fornecedor_id", "produto_id", "loja_id"),
  CONSTRAINT "fornecedor_produtos_lojas_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "fornecedor_produtos_lojas_produto_id_fkey" FOREIGN KEY ("produto_id") REFERENCES public."produtos" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "fornecedor_produtos_lojas_fornecedor_id_fkey" FOREIGN KEY ("fornecedor_id") REFERENCES public."fornecedores" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."produtos_lojas" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "produto_id" bigint NOT NULL,
  "loja_id" bigint NOT NULL,
  "preco_venda" numeric NOT NULL DEFAULT 0,
  "estoque_minimo" numeric NOT NULL DEFAULT 0,
  "ativo" integer NOT NULL DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "precos_personalizados" integer NOT NULL DEFAULT 0,
  "preco_custo" numeric,
  CONSTRAINT "produtos_lojas_produto_id_loja_id_key" UNIQUE ("produto_id", "loja_id"),
  CONSTRAINT "produtos_lojas_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "produtos_lojas_produto_id_fkey" FOREIGN KEY ("produto_id") REFERENCES public."produtos" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."usuarios" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" text NOT NULL,
  "email" text NOT NULL,
  "senha" text NOT NULL,
  "perfil" text NOT NULL DEFAULT 'OPERADOR',
  "ativo" integer DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "papel_id" bigint,
  CONSTRAINT "usuarios_email_key" UNIQUE ("email"),
  CONSTRAINT "usuarios_papel_id_fkey" FOREIGN KEY ("papel_id") REFERENCES public."papeis_acesso" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."caixas_sessoes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "loja_id" bigint NOT NULL,
  "local_id" bigint NOT NULL,
  "usuario_id" bigint NOT NULL,
  "loja_nome" text NOT NULL,
  "local_nome" text NOT NULL,
  "usuario_nome" text NOT NULL,
  "status" text NOT NULL DEFAULT 'ABERTO',
  "aberto_em" text NOT NULL DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  "fechado_em" text,
  "fechado_por_id" bigint,
  "fechado_por_nome" text,
  "saldo_inicial" numeric NOT NULL,
  "valor_contado" numeric,
  "valor_esperado" numeric,
  "diferenca" numeric,
  "quantidade_vendas" integer,
  "total_vendas" numeric,
  "resumo_json" text,
  "observacao_abertura" text,
  "observacao_fechamento" text,
  CONSTRAINT "caixas_sessoes_check_1" CHECK (status IN ('ABERTO', 'FECHADO')),
  CONSTRAINT "caixas_sessoes_check_2" CHECK (saldo_inicial >= 0),
  CONSTRAINT "caixas_sessoes_fechado_por_id_fkey" FOREIGN KEY ("fechado_por_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "caixas_sessoes_usuario_id_fkey" FOREIGN KEY ("usuario_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "caixas_sessoes_local_id_fkey" FOREIGN KEY ("local_id") REFERENCES public."locais_estoque" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "caixas_sessoes_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."executores" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" text NOT NULL,
  "nome" text NOT NULL,
  "ativo" integer NOT NULL DEFAULT 1,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "usuario_id" bigint,
  CONSTRAINT "executores_codigo_key" UNIQUE ("codigo"),
  CONSTRAINT "executores_usuario_id_fkey" FOREIGN KEY ("usuario_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."auditoria_operacoes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "executor_id" bigint NOT NULL,
  "usuario_sessao_id" bigint,
  "modulo" text NOT NULL,
  "acao" text NOT NULL,
  "entidade" text,
  "entidade_id" bigint,
  "descricao" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "auditoria_operacoes_usuario_sessao_id_fkey" FOREIGN KEY ("usuario_sessao_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "auditoria_operacoes_executor_id_fkey" FOREIGN KEY ("executor_id") REFERENCES public."executores" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."fechamentos_diarios" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "data_referencia" text NOT NULL,
  "loja_id" bigint NOT NULL,
  "dinheiro" numeric NOT NULL DEFAULT 0,
  "pix" numeric NOT NULL DEFAULT 0,
  "debito" numeric NOT NULL DEFAULT 0,
  "credito" numeric NOT NULL DEFAULT 0,
  "a_prazo" numeric NOT NULL DEFAULT 0,
  "outros" numeric NOT NULL DEFAULT 0,
  "total_informado" numeric NOT NULL DEFAULT 0,
  "executor_id" bigint,
  "usuario_id" bigint,
  "observacao" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "fechamentos_diarios_data_referencia_loja_id_key" UNIQUE ("data_referencia", "loja_id"),
  CONSTRAINT "fechamentos_diarios_usuario_id_fkey" FOREIGN KEY ("usuario_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "fechamentos_diarios_executor_id_fkey" FOREIGN KEY ("executor_id") REFERENCES public."executores" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "fechamentos_diarios_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."fechamentos_diarios_historico" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "fechamento_id" bigint NOT NULL,
  "usuario_id" bigint,
  "motivo" text,
  "dados_antes" text,
  "dados_depois" text NOT NULL,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "fechamentos_diarios_historico_usuario_id_fkey" FOREIGN KEY ("usuario_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "fechamentos_diarios_historico_fechamento_id_fkey" FOREIGN KEY ("fechamento_id") REFERENCES public."fechamentos_diarios" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."movimentacoes_estoque" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "produto_id" bigint NOT NULL,
  "tipo" text NOT NULL,
  "quantidade" numeric NOT NULL,
  "custo_unitario" numeric DEFAULT 0,
  "loja_origem_id" bigint,
  "local_origem_id" bigint,
  "loja_destino_id" bigint,
  "local_destino_id" bigint,
  "usuario_id" bigint,
  "referencia" text,
  "observacao" text,
  "justificativa" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "movimentacoes_estoque_usuario_id_fkey" FOREIGN KEY ("usuario_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "movimentacoes_estoque_local_destino_id_fkey" FOREIGN KEY ("local_destino_id") REFERENCES public."locais_estoque" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "movimentacoes_estoque_loja_destino_id_fkey" FOREIGN KEY ("loja_destino_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "movimentacoes_estoque_local_origem_id_fkey" FOREIGN KEY ("local_origem_id") REFERENCES public."locais_estoque" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "movimentacoes_estoque_loja_origem_id_fkey" FOREIGN KEY ("loja_origem_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "movimentacoes_estoque_produto_id_fkey" FOREIGN KEY ("produto_id") REFERENCES public."produtos" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."notas_entrada" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "empresa_id" bigint NOT NULL,
  "fornecedor_id" bigint,
  "loja_id" bigint,
  "local_estoque_id" bigint,
  "chave_nfe" text NOT NULL,
  "numero_nota" text,
  "serie" text,
  "modelo" text DEFAULT '55',
  "natureza_operacao" text,
  "data_emissao" text,
  "data_saida_entrada" text,
  "valor_produtos" numeric DEFAULT 0,
  "valor_frete" numeric DEFAULT 0,
  "valor_seguro" numeric DEFAULT 0,
  "valor_desconto" numeric DEFAULT 0,
  "valor_outros" numeric DEFAULT 0,
  "valor_icms" numeric DEFAULT 0,
  "valor_icms_st" numeric DEFAULT 0,
  "valor_ipi" numeric DEFAULT 0,
  "valor_pis" numeric DEFAULT 0,
  "valor_cofins" numeric DEFAULT 0,
  "valor_total" numeric DEFAULT 0,
  "quantidade_itens" integer DEFAULT 0,
  "status" text NOT NULL DEFAULT 'PENDENTE',
  "xml" text,
  "arquivo_nome" text,
  "observacao" text,
  "usuario_importacao_id" bigint,
  "usuario_efetivacao_id" bigint,
  "importado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "efetivado_em" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "notas_entrada_chave_nfe_key" UNIQUE ("chave_nfe"),
  CONSTRAINT "notas_entrada_check_1" CHECK (status IN (
            'PENDENTE',
            'EFETIVADA',
            'CANCELADA'
          )),
  CONSTRAINT "notas_entrada_usuario_efetivacao_id_fkey" FOREIGN KEY ("usuario_efetivacao_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "notas_entrada_usuario_importacao_id_fkey" FOREIGN KEY ("usuario_importacao_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "notas_entrada_local_estoque_id_fkey" FOREIGN KEY ("local_estoque_id") REFERENCES public."locais_estoque" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "notas_entrada_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "notas_entrada_fornecedor_id_fkey" FOREIGN KEY ("fornecedor_id") REFERENCES public."fornecedores" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "notas_entrada_empresa_id_fkey" FOREIGN KEY ("empresa_id") REFERENCES public."empresas" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."notas_entrada_itens" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
