  CONSTRAINT "notas_entrada_itens_fornecedor_id_fkey" FOREIGN KEY ("fornecedor_id") REFERENCES public."fornecedores" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "notas_entrada_itens_nota_entrada_id_fkey" FOREIGN KEY ("nota_entrada_id") REFERENCES public."notas_entrada" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS public."notas_entrada_parcelas" (
