  "baixado_em" text,
  "cancelado_em" text,
  "motivo_cancelamento" text,
  "caixa_sessao_id" bigint,
  CONSTRAINT "financeiro_lancamentos_check_1" CHECK (tipo IN ('ENTRADA', 'SAIDA')),
