          'PAGO',
          'RECEBIDO',
          'CANCELADO'
        )),
  CONSTRAINT "financeiro_lancamentos_usuario_baixa_id_fkey" FOREIGN KEY ("usuario_baixa_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "financeiro_lancamentos_usuario_alteracao_id_fkey" FOREIGN KEY ("usuario_alteracao_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "financeiro_lancamentos_usuario_criacao_id_fkey" FOREIGN KEY ("usuario_criacao_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "financeiro_lancamentos_nota_entrada_parcela_id_fkey" FOREIGN KEY ("nota_entrada_parcela_id") REFERENCES public."notas_entrada_parcelas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "financeiro_lancamentos_nota_entrada_id_fkey" FOREIGN KEY ("nota_entrada_id") REFERENCES public."notas_entrada" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "financeiro_lancamentos_categoria_id_fkey" FOREIGN KEY ("categoria_id") REFERENCES public."financeiro_categorias" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "financeiro_lancamentos_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "financeiro_lancamentos_fornecedor_id_fkey" FOREIGN KEY ("fornecedor_id") REFERENCES public."fornecedores" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "financeiro_lancamentos_empresa_id_fkey" FOREIGN KEY ("empresa_id") REFERENCES public."empresas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "financeiro_lancamentos_caixa_sessao_id_fkey" FOREIGN KEY ("caixa_sessao_id") REFERENCES public."caixas_sessoes" ("id") DEFERRABLE INITIALLY DEFERRED
);

