);

CREATE TABLE IF NOT EXISTS public."vendas" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "loja_id" bigint NOT NULL,
  "local_id" bigint NOT NULL,
  "usuario_id" bigint,
  "executor_id" bigint,
  "status" text NOT NULL DEFAULT 'CONCLUIDA',
  "valor_total" numeric NOT NULL DEFAULT 0,
  "observacao" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "cancelado_em" text,
  "caixa_sessao_id" bigint,
  "cliente_id" bigint,
  CONSTRAINT "vendas_check_1" CHECK (status IN (
            'CONCLUIDA',
            'CANCELADA'
          )),
  CONSTRAINT "vendas_executor_id_fkey" FOREIGN KEY ("executor_id") REFERENCES public."executores" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "vendas_usuario_id_fkey" FOREIGN KEY ("usuario_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "vendas_local_id_fkey" FOREIGN KEY ("local_id") REFERENCES public."locais_estoque" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "vendas_loja_id_fkey" FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "vendas_cliente_id_fkey" FOREIGN KEY ("cliente_id") REFERENCES public."clientes" ("id") DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT "vendas_caixa_sessao_id_fkey" FOREIGN KEY ("caixa_sessao_id") REFERENCES public."caixas_sessoes" ("id") DEFERRABLE INITIALLY DEFERRED
);

